import React, { useState } from 'react';
import { getNativeSelectState, nativeSelectStyleKeys } from '../lib/core';
import type { NativeSelectBaseProps, NativeSelectOptionBaseProps, NativeSelectOptGroupBaseProps } from '../lib/core';
import styles from './native-select.module.scss';

export interface NativeSelectProps extends Omit<React.SelectHTMLAttributes<HTMLSelectElement>, 'size' | 'value' | 'defaultValue'>, NativeSelectBaseProps {
	value?: string;
	defaultValue?: string;
	onValueChange?: (value: string) => void;
}

const NativeSelect = React.forwardRef<HTMLSelectElement, NativeSelectProps>(
	({ className = '', size = 'default', value, defaultValue = '', onValueChange, onChange, children, ...props }, ref) => {
		const [internalValue, setInternalValue] = useState(defaultValue);
		const currentValue = value !== undefined ? value : internalValue;
		const state = getNativeSelectState(currentValue);

		function handleChange(event: React.ChangeEvent<HTMLSelectElement>) {
			const next = event.target.value;

			if (value === undefined) {
				setInternalValue(next);
			}

			onValueChange?.(next);
			onChange?.(event);
		}

		return (
			<div className={styles[nativeSelectStyleKeys.wrapper]}>
				<select
					ref={ref}
					data-slot="native-select"
					data-size={size}
					data-state={state}
					value={currentValue}
					onChange={handleChange}
					className={`${styles[nativeSelectStyleKeys.select]} ${className}`}
					{...props}>
					{children}
				</select>
				<svg
					className={styles[nativeSelectStyleKeys.icon]}
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					fill="none"
					stroke="currentColor"
					strokeWidth="2"
					strokeLinecap="round"
					strokeLinejoin="round"
					aria-hidden="true"
					data-slot="native-select-icon">
					<path d="m6 9 6 6 6-6" />
				</svg>
			</div>
		);
	},
);
NativeSelect.displayName = 'NativeSelect';

export interface NativeSelectOptionProps extends React.OptionHTMLAttributes<HTMLOptionElement>, NativeSelectOptionBaseProps {}

const NativeSelectOption = React.forwardRef<HTMLOptionElement, NativeSelectOptionProps>(({ className = '', ...props }, ref) => {
	return <option ref={ref} data-slot="native-select-option" className={`${styles[nativeSelectStyleKeys.option]} ${className}`} {...props} />;
});
NativeSelectOption.displayName = 'NativeSelectOption';

export interface NativeSelectOptGroupProps extends React.OptgroupHTMLAttributes<HTMLOptGroupElement>, NativeSelectOptGroupBaseProps {}

const NativeSelectOptGroup = React.forwardRef<HTMLOptGroupElement, NativeSelectOptGroupProps>(({ className = '', children, ...props }, ref) => {
	return (
		<optgroup ref={ref} data-slot="native-select-optgroup" className={`${styles[nativeSelectStyleKeys.optGroup]} ${className}`} {...props}>
			{children}
		</optgroup>
	);
});
NativeSelectOptGroup.displayName = 'NativeSelectOptGroup';

export { NativeSelect, NativeSelectOption, NativeSelectOptGroup };
export default NativeSelect;

@use '../../../styles/variables/colors' as *;

.wrapper {
	position: relative;
	width: fit-content;
	color: $foreground;

	&:has(select:disabled) {
		opacity: 0.5;
	}
}

.select {
	appearance: none;
	width: 100%;
	min-width: 0;
	height: var(--tile-native-select-height, 2.25rem);
	border-radius: var(--tile-native-select-radius, #{$radius});
	border: var(--tile-native-select-border-width, 1px) solid var(--tile-native-select-border, #{$input});
	background-color: var(--tile-native-select-background, #{$background});
	padding: var(--tile-native-select-padding, #{$spacing-2} 2.25rem #{$spacing-2} #{$spacing-3});
	font-size: var(--tile-native-select-font-size, #{$text-sm});
	line-height: var(--tile-native-select-line-height, inherit);
	color: $foreground;
	box-shadow: var(--tile-native-select-shadow, #{$shadow-sm});
	transition:
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	cursor: pointer;

	&::placeholder {
		color: $muted-foreground;
	}

	&:hover:not(:disabled) {
		background-color: var(--tile-native-select-hover-background, #{$field-hover});
	}

	&:focus-visible {
		border-color: var(--tile-native-select-focus-border, #{$ring});
		box-shadow: var(--tile-native-select-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:disabled {
		pointer-events: none;
		cursor: not-allowed;
	}

	&[data-size='sm'] {
		height: var(--tile-native-select-sm-height, 2rem);
		font-size: var(--tile-native-select-sm-font-size, #{$text-sm});
		border-radius: var(--tile-native-select-sm-radius, #{$radius});
		padding-top: $spacing-1;
		padding-bottom: $spacing-1;
	}

	&[data-state='empty'] {
		color: $muted-foreground;
	}

	&[aria-invalid='true'] {
		border-color: $destructive;
		box-shadow: var(--tile-native-select-error-shadow, #{$shadow-sm});

		&:focus-visible {
			box-shadow: var(--tile-native-select-error-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$destructive} 20%, transparent));
		}
	}
}

.icon {
	pointer-events: none;
	position: absolute;
	top: 50%;
	right: 0.875rem;
	transform: translateY(-50%);
	width: 1rem;
	height: 1rem;
	color: $muted-foreground;
	opacity: 0.5;
	user-select: none;
}

.option {
	background-color: Canvas;
	color: CanvasText;
}

.optGroup {
	background-color: Canvas;
	color: CanvasText;
}
